#[test]
fn a_contended_renderer_io_poll_wakes_itself_until_the_exact_session_can_register(){
 let _serial=SOURCE_LAWS.lock().unwrap();install_launch();let law:serde_json::Value=serde_json::from_str(include_str!("../../../../../../🧪️tests/🧫️fixtures/📄️native-asset-response/🔣️.json")).unwrap();let law=&law["rendererIoContention"];assert_eq!(law["registrationState"],"checkedOut");assert_eq!(law["exactGenerationLive"],true);assert_eq!(law["poll"],"pending");
 struct CountWake(std::sync::atomic::AtomicUsize);impl std::task::Wake for CountWake{fn wake(self:std::sync::Arc<Self>){self.0.fetch_add(1,Ordering::AcqRel);}fn wake_by_ref(self:&std::sync::Arc<Self>){self.0.fetch_add(1,Ordering::AcqRel);}}
 let wake=std::sync::Arc::new(CountWake(AtomicUsize::new(0)));let waker=Waker::from(wake.clone());let mut context=Context::from_waker(&waker);let mut open=RendererSourceIoOpen{path:RendererIoPath::new(["","",""]),handle:None,mode:RendererSourceIoMode::Resident,startup:true,completed:false};assert!(Pin::new(&mut open).poll(&mut context).is_pending());let handle=open.handle.as_ref().unwrap();let(slot,generation)=(handle.slot,handle.generation);
 wait_until(||with_node(slot,generation,|_|{wake.0.store(0,Ordering::Release);assert!(Pin::new(&mut open).poll(&mut context).is_pending());assert_eq!(wake.0.load(Ordering::Acquire),law["wakeCount"].as_u64().unwrap()as usize);true}).unwrap_or(false));drop(open);wait_until(||generation_closed(slot,generation));assert_eq!(usize::from(generation_live(slot,generation)),law["terminalOwners"].as_u64().unwrap()as usize);
}

#[test]
fn mounted_registry_max_plus_one_zero_pump_drop_and_generation_are_exact(){
 let _serial=SOURCE_LAWS.lock().unwrap();install_launch();let mut handles=Vec::with_capacity(INVOCATIONS);for _ in 0..INVOCATIONS{handles.push(claim_renderer_source(RendererSourceIoMode::World,true).unwrap());}let refusal=match claim_renderer_source(RendererSourceIoMode::Resident,true){Ok(_)=>panic!("one beyond the actual fixed source maximum must be refused"),Err(error)=>error};assert_eq!(refusal.kind,RendererSourceIoFailureKind::RegistryFull);drop(refusal);let last=handles.last().unwrap();let(last_slot,last_generation)=(last.slot,last.generation);
 let pointer=with_node(last_slot,last_generation,|node|{for _ in 0..64{if node.caller.ready(){break}node.pump();}assert!(node.caller.ready());node.prepare(RendererIoPath::new(["original-last-source-path","",""]));let Some(NativeIoRequest::ReadBytes(path))=node.request.as_ref()else{panic!("last actual source retains its original received request")};path.as_os_str().as_encoded_bytes().as_ptr()as usize}).unwrap();assert_eq!(pump_renderer_source_io_sessions(0),0);assert_eq!(with_node(last_slot,last_generation,|node|node.request.as_ref().and_then(|request|match request{NativeIoRequest::ReadBytes(path)=>Some(path.as_os_str().as_encoded_bytes().as_ptr()as usize),_=>None}).or_else(||node.invocation.as_ref().and_then(RendererOriginalIoNode::request_backing_identity).map(|pointer|pointer as usize))).flatten(),Some(pointer));
 let keys:Vec<_>=handles.iter().map(|handle|(handle.slot,handle.generation)).collect();drop(handles);wait_until(||keys.iter().all(|&(slot,generation)|generation_closed(slot,generation)));let replacement=claim_renderer_source(RendererSourceIoMode::Resident,true).unwrap();let prior=keys.iter().find(|&&(slot,_)|slot==replacement.slot).unwrap().1;assert!(replacement.generation>prior);let key=(replacement.slot,replacement.generation);drop(replacement);wait_until(||generation_closed(key.0,key.1));
}

#[test]
fn renderer_source_io_contiguous_keeps_one_original_startup_through_all_pages_and_compiler_borrow(){
 let _serial=SOURCE_LAWS.lock().unwrap();install_launch();let path=std::env::temp_dir().join(format!("semio-source-contiguous-{}",std::process::id()));
 for length in[0usize,16385,semio_framework_job::JOB_PAYLOAD_OPERATION_BYTES+1,268435456]{
  let data:Vec<u8>=(0..length).map(|index|(index%251)as u8).collect();std::fs::write(&path,&data).unwrap();let mut read=read_renderer_source_bytes(&path,268435456);let supplied=drive(&mut read).unwrap();assert_eq!(supplied.bytes(),data.as_slice());let source=supplied.source_identity();let handle=read.open.handle.as_ref().or(read.handle.as_ref());assert!(handle.is_none());let slot=SLOTS.iter().position(|slot|slot.node.lock().unwrap().as_ref().is_some_and(|node|node.bytes_identity==Some(source))).unwrap();let generation=SLOTS[slot].generation.load(Ordering::Acquire);
  wait_until(||with_node(slot,generation,|node|node.invocation.is_none()).unwrap_or(false));assert!(with_node(slot,generation,|node|!node.caller.original_loans_are_returned()&&node.contiguous_extent==Some(length as u64)).unwrap());assert!(!generation_closed(slot,generation));assert_eq!(semio_framework_hash::hash(supplied.bytes()),semio_framework_hash::hash(&data));
  let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(supplied));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));wait_until(||generation_closed(slot,generation));
 }
 std::fs::File::create(&path).unwrap().set_len(268435457).unwrap();let mut read=read_renderer_source_bytes(&path,268435456);let error=match drive(&mut read){Ok(_)=>panic!("maximum-plus-one file must refuse before contiguous/page birth"),Err(error)=>error};assert_eq!(error.kind,RendererSourceIoFailureKind::Extent(NativeIoStreamRefusal{length:268435457,maximum_bytes:268435456}));let handle=error.handle.as_ref().unwrap();let(slot,generation)=(handle.slot,handle.generation);assert!(with_node(slot,generation,|node|node.contiguous.is_none()&&node.invocation.as_ref().unwrap().result_page(0).is_none()).unwrap());drop(error);wait_until(||generation_closed(slot,generation));std::fs::remove_file(path).unwrap();eprintln!("[DEBUG] actual startup source/exact contiguous backing kept one path and original source through empty,16KiB+1,4MiB+1,and256MiB inputs/compiler hash borrow; original consumer return heap0, paid source close,256MiB+1 refused before payload birth");
}
