 let _serial=SOURCE_LAWS.lock().unwrap();install_launch();let root=std::env::temp_dir().join(format!("semio-source-directory-{}",std::process::id()));std::fs::create_dir_all(&root).unwrap();let path=root.join("selected.wasm");let data=b"original component input";std::fs::write(&path,data).unwrap();std::fs::write(root.join("ignored.json"),b"{}").unwrap();let mut find=Box::pin(find_renderer_wasm_path(&root));let selected=drive(&mut find).unwrap().unwrap();assert_eq!(selected.path(),path);let identity=selected.source_identity();let slot=SLOTS.iter().position(|slot|slot.node.lock().unwrap().as_ref().is_some_and(|node|node.path_identity==Some(identity))).unwrap();let generation=SLOTS[slot].generation.load(Ordering::Acquire);
 wait_until(||with_node(slot,generation,|node|node.invocation.is_none()).unwrap_or(false));assert!(PATH_RETURNS.retains_source(identity));assert!(with_node(slot,generation,|node|!node.caller.original_loans_are_returned()).unwrap());let clock=with_node(slot,generation,|node|node.caller.original_clock_binding()).unwrap();let mut read=read_renderer_source_bytes(selected.path(),268435456);let bytes=drive(&mut read).unwrap();assert_eq!(bytes.bytes(),data);assert!(with_node(slot,generation,|node|node.caller.original_clock_binding()==clock).unwrap());drop(bytes);drop(read);
 let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(selected));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));wait_until(||generation_closed(slot,generation));std::fs::remove_file(&path).unwrap();let mut empty=Box::pin(find_renderer_wasm_path(&root));assert!(drive(&mut empty).unwrap().is_none());wait_until(||!renderer_source_io_pending());std::fs::remove_file(root.join("ignored.json")).unwrap();std::fs::remove_dir(root).unwrap();eprintln!("[DEBUG] actual directory worker selected only wasm, retained same original path supplier/clock through nested component read, late consumer Drop0 woke paid return, no-match returned None with original cleanup");
