#[test]
fn renderer_source_io_resident_and_modification_observe_only_scalars_and_borrowed_original_paths(){
 let _serial=SOURCE_LAWS.lock().unwrap();install_launch();let mut resident=Box::pin(read_renderer_resident_bytes());let bytes=drive(&mut resident).unwrap();assert!(bytes.is_none_or(|bytes|bytes>0));wait_until(||!renderer_source_io_pending());let path=std::env::temp_dir().join(format!("semio-source-modified-{}",std::process::id()));std::fs::write(&path,b"original metadata").unwrap();let expected=std::fs::metadata(&path).unwrap().modified().unwrap();let mut handle=start_renderer_modified().unwrap();let(slot,generation)=(handle.slot,handle.generation);wait_until(||handle.prepare_modified(&path).unwrap());let clock=with_node(slot,generation,|node|node.caller.original_clock_binding()).unwrap();let mut observed=None;
 wait_until(||{let(answer,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||handle.try_modified(|value|{let(actual,time)=value.expect("one actual input has one borrowed result");assert_eq!(actual,path);assert_eq!(time,expected);true}));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if let Some(answer)=answer{observed=Some(answer.unwrap());true}else{false}});assert_eq!(observed,Some(true));assert_eq!(handle.try_modified(|_|panic!("same observation cannot be replayed")),Some(Err(RendererSourceIoFailureKind::Stale)));assert!(with_node(slot,generation,|node|node.caller.original_clock_binding()==clock&&node.invocation.as_ref().unwrap().result_modified(0).unwrap().0==path).unwrap());drop(handle);wait_until(||generation_closed(slot,generation));std::fs::remove_file(&path).unwrap();
 let mut missing=start_renderer_modified().unwrap();let(slot,generation)=(missing.slot,missing.generation);wait_until(||missing.prepare_modified(&path).unwrap());let mut failure=None;wait_until(||if let Some(answer)=missing.try_modified(|_|panic!("failed metadata cannot become an absent successful result")){failure=Some(answer.unwrap_err());true}else{false});let error=missing.failure(failure.unwrap());assert_eq!(error.kind,RendererSourceIoFailureKind::NativeFault);assert!(error.to_string().contains(path.file_name().unwrap().to_str().unwrap()));assert!(with_node(slot,generation,|node|node.invocation.is_some()).unwrap());drop(error);wait_until(||generation_closed(slot,generation));eprintln!("[DEBUG] actual RSS returned only Copy scalar; metadata borrowed exact path/time once with heap0, same original clock, full missing-file native fault retained through paid close");
}

