 with_node(slot,generation,|node|{node.prepare(RendererIoPath::from_path(&path));for _ in 0..128{if node.contiguous.as_ref().is_some_and(|bytes|bytes.retained_length()==16384){break}node.pump();}assert_eq!(node.contiguous.as_ref().unwrap().retained_length(),16384);std::fs::OpenOptions::new().write(true).open(&path).unwrap().set_len(16384).unwrap();}).unwrap();let error=match drive(&mut read){Ok(_)=>panic!("changed input extent cannot publish incomplete compiler bytes"),Err(error)=>error};assert_eq!(error.kind,RendererSourceIoFailureKind::ChangedExtent{expected:32769,actual:16384});assert!(with_node(slot,generation,|node|node.contiguous.as_ref().unwrap().retained_length()==16384&&node.published_bytes.is_none()&&!node.caller.original_loans_are_returned()).unwrap());drop(error);wait_until(||generation_closed(slot,generation));std::fs::remove_file(path).unwrap();eprintln!("[DEBUG] deterministic on-disk extent change after first bounded page produced typed original refusal; exact partial backing/source stayed owned until genuine paid cleanup, no partial compiler input publication");
