 with_node(slot,generation,|node|{node.prepare(RendererIoPath::from_path(&path));for _ in 0..64{if node.contiguous.as_ref().is_some_and(OriginalContiguousJobBytes::ready){break}node.pump();}let backing=node.contiguous.as_ref().expect("original loan/backing candidate");assert!(backing.ready());assert!(backing.borrowed_bytes().unwrap().is_empty());assert!(!node.caller.original_loans_are_returned());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(read.take()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(SLOTS[slot].detached.load(Ordering::Acquire));}).unwrap();wait_until(||generation_closed(slot,generation));std::fs::remove_file(path).unwrap();eprintln!("[DEBUG] cancellation during checked-out original contiguous birth retained the exact unfilled backing and actual supplier/invocation owners; consumer Drop released0, original cleanup reached exact generation vacancy");
