fn install_launch(){let admission=format!("{{\"version\":1,\"declaration\":{},\"scriptOwner\":\"fixture:renderer-original-io\",\"scriptDeadlineEpochMilliseconds\":null}}",include_str!("../../../../⌨️native-entrypoint/🎟️launch/🔣️.json"));crate::native_launch::install_native_launch_fixture(&admission).unwrap();let _=renderer_worker_pool();}
fn wait_until(mut ready:impl FnMut()->bool){let deadline=std::time::Instant::now()+std::time::Duration::from_secs(120);while !ready(){assert!(std::time::Instant::now()<deadline,"actual original source/worker cleanup did not reach its expected frontier");pump_renderer_source_io_sessions(1);std::thread::yield_now();}}
fn drive<F:Future+Unpin>(future:&mut F)->F::Output{let waker=std::task::Waker::from(std::sync::Arc::new(LawWake));let mut context=Context::from_waker(&waker);let mut answer=None;wait_until(||match Pin::new(&mut *future).poll(&mut context){Poll::Ready(value)=>{answer=Some(value);true},Poll::Pending=>false});answer.unwrap()}
fn generation_closed(slot:usize,generation:u64)->bool{SLOTS[slot].generation.load(Ordering::Acquire)==generation&&matches!(SLOTS[slot].state.load(Ordering::Acquire),VACANT|EXHAUSTED)}

#[test]
fn renderer_source_io_global_world_keeps_original_source_until_late_return(){
 let _serial=SOURCE_LAWS.lock().unwrap();install_launch();let law:serde_json::Value=serde_json::from_str(include_str!("../🔣️.json")).unwrap();
 let path=std::env::temp_dir().join(format!("semio-source-world-{}",std::process::id()));let count=2*semio_framework_job::JOB_PAYLOAD_PAGE_BYTES+7;let contents:Vec<u8>=(0..count).map(|index|(index%251)as u8).collect();std::fs::write(&path,&contents).unwrap();
 let text=path.to_str().unwrap();let mut open=open_renderer_source_io(RendererIoPath::new([text,"",""]));let mut handle=drive(&mut open).unwrap();let index=handle.slot;let generation=handle.generation;
 let clock=with_node(index,generation,|node|node.caller.original_clock_binding()).unwrap();
 let mut authority=WorldAssetIoAuthority::default();authority.reserve(1,1,WorldAssetRequestKind::Glb,"original-global.glb",count).unwrap();let mut world=authority.take_next().unwrap();let mut source=None;
 for ordinal in [2usize,1,0]{let page={let mut next=handle.next_page();drive(&mut next).unwrap().unwrap()};assert_eq!(page.original_page_index(),ordinal);assert_eq!(*source.get_or_insert(page.source_identity()),page.source_identity());let pointer=page.bytes().as_ptr();let page=WorldAssetResponsePage::try_from_original(page).unwrap();assert_eq!(page.bytes().as_ptr(),pointer);assert_eq!(page.bytes(),&contents[ordinal*semio_framework_job::JOB_PAYLOAD_PAGE_BYTES..((ordinal+1)*semio_framework_job::JOB_PAYLOAD_PAGE_BYTES).min(count)]);world.push_page_at(ordinal as u16,page).unwrap();}
 assert!({let mut next=handle.next_page();drive(&mut next).unwrap().is_none()});world.seal().unwrap();drop(handle);
 wait_until(||with_node(index,generation,|node|node.invocation.as_ref().is_some_and(RendererOriginalIoNode::producer_is_empty)).unwrap_or(false));
 assert!(with_node(index,generation,|node|node.caller.original_clock_binding()==clock&&!node.caller.original_loans_are_returned()).unwrap());assert!(!generation_closed(index,generation));
 for _ in 0..3{let page=world.take_decode_page().unwrap().unwrap();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(page));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
 wait_until(||generation_closed(index,generation));world.begin_close();while !world.close_step(){}authority.return_owner(world).unwrap();authority.begin_close();while !authority.close_step(){}assert!(authority.terminal_is_empty());assert_eq!(law["sourceBirths"],1);assert_eq!(law["pathBirths"],1);std::fs::remove_file(path).unwrap();eprintln!("[DEBUG] actual fixed native registry/real worker/World3-page route kept same original clock/source after producer and initiating handle finished; late consumer returns woke original cleanup and vacated exact generation");
}

#[test]
fn renderer_source_io_cancelled_path_birth_keeps_exact_original_candidate_and_cleans_it(){
 let _serial=SOURCE_LAWS.lock().unwrap();install_launch();let text="original-cancelled-received-path";let path=RendererIoPath::new([text,"",""]);let mut open=Some(open_renderer_source_io(path));let waker=std::task::Waker::from(std::sync::Arc::new(LawWake));let mut context=Context::from_waker(&waker);assert!(Pin::new(open.as_mut().unwrap()).poll(&mut context).is_pending());
 let handle=open.as_ref().unwrap().handle.as_ref().unwrap();let index=handle.slot;let generation=handle.generation;wait_until(||with_node(index,generation,|node|node.caller.ready()).unwrap_or(false));
 let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let callback:Box<dyn FnOnce()+Send+'static>=Box::new(renderer_source_io_worker);drop(callback)});assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
 with_node(index,generation,|node|{let before=node.caller.retained_spent();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||node.prepare(path));let after=node.caller.retained_spent();assert_eq!((heap.requested_bytes,heap.released_bytes),(text.len(),0));assert_eq!(after.retained_capacity_bytes-before.retained_capacity_bytes,text.len());assert_eq!(after.copied_bytes-before.copied_bytes,text.len());assert!(node.request_committed);let NativeIoRequest::ReadBytes(request)=node.request.as_ref().unwrap()else{panic!("original received path")};assert_eq!(request.as_os_str().as_encoded_bytes(),text.as_bytes());drop(open.take());assert!(SLOTS[index].detached.load(Ordering::Acquire));}).unwrap();
 wait_until(||generation_closed(index,generation));eprintln!("[DEBUG] actual original decoder received one exact path backing; cancellation retained candidate in fixed slot, zero-capture pool callback born/released0, original source paid orphan request and complete roots before exact slot vacancy");
}

